import { createHash } from "node:crypto";
import { createConnection, createServer } from "node:net";
import { splitLines } from "./dotenv.ts";
import type { Service } from "./services.ts";

// The core of `pnpm dev:ports`: which ports this checkout's dev servers take, and the
// values each service needs to reach the others on them.
//
// The main checkout keeps the pinned ports from `SERVICES`. A linked worktree hashes its
// absolute root to a block `k` from 0 to 999 and takes `10000 + 10k + slot`, where a
// frontend's slot is `devPort - 3000` (0 to 4) and a backend's is `devPort - 4000 + 5`
// (5 to 9). Two worktrees therefore run `pnpm dev` at the same time, and a rerun lands
// on the same ports.
//
// The values land in a marked block in each service's `.env.local`, beside the `.env`
// that `pnpm env:setup` writes. Vite and the Cloudflare plugin both read `.env.local`
// over `.env`, and `env:setup` never touches the block.
//
// Everything here is pure except `isPortListening`. `scripts/dev-ports.ts` does the git
// calls and the file writes.

/** The record of this checkout's assignment, at the checkout root. Gitignored. */
export const RECORD_FILE = ".devports.json";

/** The file beside each service's `.env` that holds the block. */
export const LOCAL_FILE = ".env.local";

export const BLOCK_START =
  "# >>> dev:ports (generated by pnpm dev:ports; do not edit inside)";
export const BLOCK_END = "# <<< dev:ports";

/** How many blocks there are, and the first port of block 0. */
export const BLOCK_COUNT = 1000;
const BLOCK_BASE = 10_000;
const BLOCK_SIZE = 10;

/** The browser services: a page served on one of these ports calls the api. */
const BROWSER_PORTS = new Set([3000, 3001, 3002]);

/** What `.devports.json` holds. `block` and `cookiePrefix` are null in the main checkout. */
export interface DevPortsRecord {
  block: number | null;
  host: string;
  cookiePrefix: string | null;
  services: Record<string, number>;
}

/** A service row that has a dev server and a file to write its block beside. */
export type PortService = Service & { devPort: number; file: string };

/** The sha256 of the checkout root, as hex. The block and the cookie prefix both come from it. */
export function checkoutHash(root: string): string {
  return createHash("sha256").update(root).digest("hex");
}

/** The block a hash points at, before any collision moves it. */
export function homeBlock(hash: string): number {
  return Number.parseInt(hash.slice(0, 8), 16) % BLOCK_COUNT;
}

/** The auth cookie prefix of a linked worktree, so its session never overwrites another's. */
export function cookiePrefixFor(hash: string): string {
  return `wt${hash.slice(0, 6)}`;
}

/** The rows `dev:ports` writes for: a dev port and a file. */
export function portServices(services: Service[]): PortService[] {
  return services.filter(
    (service): service is PortService =>
      service.devPort !== undefined && service.file !== undefined
  );
}

/** A service's place in a block. A devPort outside 3000–3004 and 4000–4004 throws. */
export function portSlot(service: Pick<Service, "name" | "devPort">): number {
  const port = service.devPort;
  if (port !== undefined && port >= 3000 && port <= 3004) {
    return port - 3000;
  }
  if (port !== undefined && port >= 4000 && port <= 4004) {
    return port - 4000 + 5;
  }
  throw new Error(
    `The ${service.name} service has devPort ${String(port)} in packages/env/src/services.ts. pnpm dev:ports takes 3000 to 3004 for a frontend and 4000 to 4004 for a backend. Move it into one of those ranges.`
  );
}

/** Each service's port: the pinned one with no block, `10000 + 10k + slot` in block `k`. */
export function blockPorts(
  block: number | null,
  services: Pick<Service, "name" | "devPort">[]
): Record<string, number> {
  const ports: Record<string, number> = {};
  for (const service of services) {
    const slot = portSlot(service);
    ports[service.name] =
      block === null
        ? (service.devPort ?? 0)
        : BLOCK_BASE + BLOCK_SIZE * block + slot;
  }
  return ports;
}

/**
 * The block this checkout takes.
 *
 * A recorded block stays while no other worktree records it. Its own listeners do not
 * count: they are this checkout's running servers. Otherwise probe from `home` up,
 * wrapping at 999, past every block another worktree records or a port of which listens.
 */
export async function chooseBlock(options: {
  home: number;
  recorded: number | null | undefined;
  claimed: Set<number>;
  isListening: (block: number) => Promise<boolean>;
}): Promise<number> {
  const { home, recorded, claimed, isListening } = options;
  if (recorded !== null && recorded !== undefined && !claimed.has(recorded)) {
    return recorded;
  }
  for (let offset = 0; offset < BLOCK_COUNT; offset += 1) {
    const block = (home + offset) % BLOCK_COUNT;
    if (claimed.has(block)) {
      continue;
    }
    // One block at a time, in order, so the first free block wins.
    // oxlint-disable-next-line no-await-in-loop
    if (!(await isListening(block))) {
      return block;
    }
  }
  throw new Error(
    "pnpm dev:ports found every block taken by another worktree or a listening port. Stop the dev servers you no longer need, or remove stale worktrees with git worktree prune."
  );
}

/** Every worktree path in `git worktree list --porcelain` output. */
export function parseWorktreeList(porcelain: string): string[] {
  return splitLines(porcelain)
    .filter((line) => line.startsWith("worktree "))
    .map((line) => line.slice("worktree ".length));
}

/** A `.devports.json` text as a record, or undefined when it is missing or malformed. */
export function parseRecord(text?: string): DevPortsRecord | undefined {
  if (text === undefined) {
    return undefined;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text) as unknown;
  } catch {
    return undefined;
  }
  if (typeof parsed !== "object" || parsed === null) {
    return undefined;
  }
  const { block, host, cookiePrefix, services } = parsed as Record<
    string,
    unknown
  >;
  const blockOk =
    block === null ||
    (Number.isInteger(block) &&
      (block as number) >= 0 &&
      (block as number) < BLOCK_COUNT);
  if (
    !blockOk ||
    typeof host !== "string" ||
    (cookiePrefix !== null && typeof cookiePrefix !== "string") ||
    typeof services !== "object" ||
    services === null
  ) {
    return undefined;
  }
  return {
    block: block as number | null,
    host,
    cookiePrefix: cookiePrefix as string | null,
    services: services as Record<string, number>,
  };
}

/** `host` when it is a bare host name or address, the shape a URL's host part takes. */
export function checkHost(host: string): string {
  if (!/^[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?$/.test(host)) {
    throw new Error(
      `DEV_HOST is "${host}". It must be a bare host name or address, such as localhost or devaloy, with no scheme and no port. Set it in packages/env/.env, or pass --host <name>.`
    );
  }
  return host;
}

/** The browser services' origins: localhost, plus `host` when it differs. */
export function browserOrigins(
  services: Pick<Service, "name" | "devPort">[],
  ports: Record<string, number>,
  host: string
): string[] {
  return services
    .filter((service) => BROWSER_PORTS.has(service.devPort ?? 0))
    .flatMap((service) => {
      const port = ports[service.name];
      return host === "localhost"
        ? [`http://localhost:${port}`]
        : [`http://localhost:${port}`, `http://${host}:${port}`];
    });
}

/**
 * The keys each service's block holds, in write order. Every service takes `DEV_PORT`. A
 * browser service takes the api and site URLs on `host`, since a page and its api must
 * share one host for the `SameSite=Lax` session cookie. The api takes its own auth URL,
 * the CORS list, and in a linked worktree the cookie prefix.
 */
export function serviceBlocks(options: {
  services: Pick<Service, "name" | "devPort">[];
  ports: Record<string, number>;
  host: string;
  cookiePrefix: string | null;
}): Map<string, [string, string][]> {
  const { services, ports, host, cookiePrefix } = options;
  const apiPort = ports.api;
  const webPort = ports.web;
  const blocks = new Map<string, [string, string][]>();
  for (const service of services) {
    const entries: [string, string][] = [
      ["DEV_PORT", String(ports[service.name])],
    ];
    if (BROWSER_PORTS.has(service.devPort ?? 0)) {
      if (apiPort !== undefined) {
        entries.push(["PUBLIC_API_URL", `http://${host}:${apiPort}`]);
      }
      if (webPort !== undefined) {
        entries.push(["PUBLIC_SITE_URL", `http://${host}:${webPort}`]);
      }
    }
    if (service.name === "api") {
      entries.push(
        ["BETTER_AUTH_URL", `http://${host}:${ports[service.name]}`],
        ["CORS_ORIGINS", browserOrigins(services, ports, host).join(",")]
      );
      if (cookiePrefix !== null) {
        entries.push(["AUTH_COOKIE_PREFIX", cookiePrefix]);
      }
    }
    blocks.set(service.name, entries);
  }
  return blocks;
}

/** The block's lines, markers included. */
export function renderBlock(entries: [string, string][]): string[] {
  return [
    BLOCK_START,
    ...entries.map(([key, value]) => `${key}=${value}`),
    BLOCK_END,
  ];
}

/**
 * `text` with its block replaced by `block`, or removed when `block` is undefined. Every
 * other line stays. The block always goes last, so it wins over a key typed above it. An
 * empty result means nothing but the block was in the file.
 */
export function rewriteBlock(text: string, block?: string[]): string {
  const lines = splitLines(text);
  const start = lines.indexOf(BLOCK_START);
  if (start !== -1) {
    const end = lines.indexOf(BLOCK_END, start);
    if (end === -1) {
      throw new Error(
        `The file has a "${BLOCK_START}" line and no end line "${BLOCK_END}". Fix the block by hand, or delete it, and run pnpm dev:ports again.`
      );
    }
    // The blank line above the block is the separator this function wrote with it.
    const from =
      start > 0 && lines[start - 1]?.trim() === "" ? start - 1 : start;
    lines.splice(from, end - from + 1);
  }
  while (lines.length > 0 && lines.at(-1)?.trim() === "") {
    lines.pop();
  }
  if (block !== undefined) {
    if (lines.length > 0) {
      lines.push("");
    }
    lines.push(...block);
  }
  return lines.length > 0 ? `${lines.join("\n")}\n` : "";
}

function connects(port: number, host: string): Promise<boolean> {
  // A socket reports through events, not a promise, so this wraps it in one.
  // oxlint-disable-next-line promise/avoid-new
  return new Promise((resolve) => {
    const socket = createConnection({ port, host });
    socket.setTimeout(500);
    const done = (open: boolean): void => {
      socket.destroy();
      resolve(open);
    };
    socket.once("connect", () => done(true));
    socket.once("timeout", () => done(false));
    socket.once("error", () => done(false));
  });
}

function bindFails(port: number): Promise<boolean> {
  // A server reports through events, not a promise, so this wraps it in one.
  // oxlint-disable-next-line promise/avoid-new
  return new Promise((resolve) => {
    const server = createServer();
    server.once("error", (error: NodeJS.ErrnoException) => {
      resolve(error.code === "EADDRINUSE");
    });
    server.listen({ port, exclusive: true }, () => {
      server.close(() => resolve(false));
    });
  });
}

/**
 * True when something listens on `port` now. A connect to each loopback address catches
 * a server on `localhost`; a bind on the wildcard catches one that `--host` put on every
 * address, or on a single non-loopback one.
 */
export async function isPortListening(port: number): Promise<boolean> {
  const loopback = await Promise.all([
    connects(port, "127.0.0.1"),
    connects(port, "::1"),
  ]);
  if (loopback.includes(true)) {
    return true;
  }
  return bindFails(port);
}
